n// Control colors\n$success-color: #32b643 !default;\n$warning-color: #ffb700 !default;\n$error-color: #e85600 !default;\n\n// Other colors\n$highlight-color: #ffe9b3 !default;\n\n$border-radius: 3%;\n\n// Z-index\n$zindex-0: 1 !default;\n$zindex-1: 100 !default;\n$zindex-2: 200 !default;\n$zindex-3: 300 !default;\n$zindex-4: 400 !default;\n',"@use '@prismal/react/lib/styles/theme.scss';\n.example-landing-page {\n    font-family: sans-serif;\n    display: flex;\n    flex-direction: column;\n    overflow-x: hidden;\n}\n\n.landing-nav {\n    /* Header sets width:100% (content-box) on this element; adding horizontal\n       padding without border-box would push it past its container's edge\n       (masked here by .example-landing-page's overflow-x:hidden, but still\n       worth fixing at the source). */\n    box-sizing: border-box;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 1.5rem;\n    padding: 0.75rem 1.5rem;\n    background: white;\n}\n\n.landing-brand {\n    font-weight: 700;\n    font-size: 1.25rem;\n    white-space: nowrap;\n}\n\n.landing-nav-menu {\n    display: flex;\n    flex-direction: row;\n    gap: 1.5rem;\n    flex: 1;\n    justify-content: center;\n}\n\n.landing-nav-menu .prismal-menu-item {\n    cursor: pointer;\n    white-space: nowrap;\n}\n\n.landing-hero {\n    position: relative;\n    padding: 5rem 1.5rem;\n    text-align: center;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 1.25rem;\n    overflow: hidden;\n}\n\n.landing-hero-blob {\n    position: absolute;\n    top: -6rem;\n    left: 50%;\n    transform: translateX(-50%);\n    width: 30rem;\n    height: 30rem;\n    border-radius: 50%;\n    background: radial-gradient(circle, rgba(90, 110, 220, 0.25), transparent 70%);\n    pointer-events: none;\n    z-index: 0;\n}\n\n.landing-hero-title {\n    max-width: 40rem;\n    position: relative;\n}\n\n.landing-hero-subtitle {\n    max-width: 34rem;\n    opacity: 0.75;\n    position: relative;\n}\n\n.landing-features,\n.landing-testimonials,\n.landing-pricing,\n.landing-faq,\n.landing-newsletter {\n    /* width:100% + padding under content-box overflows past the section's\n       own max-width (visible on .landing-newsletter, which resets max-width\n       to none and so has nothing left to clip the overflow). */\n    box-sizing: border-box;\n    padding: 3rem 1.5rem;\n    max-width: 64rem;\n    margin: 0 auto;\n    width: 100%;\n}\n\n.landing-section-title {\n    text-align: center;\n    margin-bottom: 1.5rem;\n}\n\n.landing-features-grid {\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: center;\n    gap: 1rem;\n}\n\n.landing-feature-card {\n    flex: 1 1 16rem;\n    max-width: 20rem;\n}\n\n.landing-feature-body {\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    text-align: center;\n    gap: 0.5rem;\n    height: 100%;\n    justify-content: center;\n}\n\n.landing-testimonial-slider {\n    height: 14rem;\n}\n\n.landing-testimonial-card {\n    height: 100%;\n    max-width: 30rem;\n    text-align: center;\n}\n\n.landing-testimonial-body {\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    gap: 0.75rem;\n    height: 100%;\n}\n\n.landing-testimonial-quote {\n    font-style: italic;\n}\n\n.landing-testimonial-name {\n    font-weight: 600;\n}\n\n.landing-testimonial-role {\n    opacity: 0.6;\n}\n\n.landing-pricing-toggle {\n    display: flex;\n    justify-content: center;\n    margin-bottom: 2rem;\n}\n\n.landing-pricing-grid {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 1.25rem;\n    justify-content: center;\n}\n\n.landing-pricing-card {\n    flex: 1 1 14rem;\n    max-width: 18rem;\n    display: flex;\n    flex-direction: column;\n    gap: 0.5rem;\n}\n\n.landing-pricing-description {\n    opacity: 0.7;\n}\n\n.landing-pricing-price {\n    display: flex;\n    align-items: baseline;\n    gap: 0.35rem;\n    margin: 0.5rem 0;\n}\n\n.landing-pricing-features {\n    list-style: none;\n    margin: 0 0 0.75rem;\n    padding: 0;\n    display: flex;\n    flex-direction: column;\n    gap: 0.35rem;\n    font-size: 0.85rem;\n    opacity: 0.8;\n}\n\n.landing-faq-list {\n    display: flex;\n    flex-direction: column;\n    gap: 0.75rem;\n    max-width: 40rem;\n    margin: 0 auto;\n}\n\n.landing-newsletter {\n    text-align: center;\n    background: #f7f7f8;\n    max-width: none;\n}\n\n.landing-newsletter-form {\n    max-width: 26rem;\n    margin: 1rem auto 0;\n}\n\n.landing-newsletter-form .form-fields {\n    align-items: center;\n}\n\n.landing-footer {\n    background: #1c1e26;\n    color: #f2f2f4;\n    padding: 2rem 1.5rem;\n    display: flex;\n    flex-direction: column;\n    gap: 1.5rem;\n}\n\n.landing-footer-logo {\n    display: inline-block;\n    padding: 0.35rem 1rem;\n    margin-right: 1rem;\n    border: 1px solid rgba(255, 255, 255, 0.2);\n    border-radius: 999px;\n    font-size: 0.85rem;\n}\n\n.landing-footer-menu {\n    display: flex;\n    flex-direction: row;\n    gap: 1.5rem;\n    justify-content: center;\n}\n\n.landing-footer-menu .prismal-menu-item {\n    cursor: pointer;\n    opacity: 0.8;\n}\n"],sourceRoot:""}]);const __WEBPACK_DEFAULT_EXPORT__=___CSS_LOADER_EXPORT___},"../../node_modules/css-loader/dist/runtime/api.js"(module){module.exports=function(cssWithMappingToString){var list=[];return list.toString=function toString(){return this.map(function(item){var content="",needLayer=void 0!==item[5];return item[4]&&(content+="@supports (".concat(item[4],") {")),item[2]&&(content+="@media ".concat(item[2]," {")),needLayer&&(content+="@layer".concat(item[5].length>0?" ".concat(item[5]):""," {")),content+=cssWithMappingToString(item),needLayer&&(content+="}"),item[2]&&(content+="}"),item[4]&&(content+="}"),content}).join("")},list.i=function i(modules,media,dedupe,supports,layer){"string"==typeof modules&&(modules=[[null,modules,void 0]]);var alreadyImportedModules={};if(dedupe)for(var k=0;k<this.length;k++){var i